import{accountAuthClient,OWNER_PROJECT_URL,OWNER_PUBLIC_KEY}from './owner-auth.js';
import{createCounterSync}from './counter-sync-core.js';
import{esc}from './ui.js';
let engine=null,session=null,timer=null,busy=null,status='local',reason='',host=null;
export const counterSyncStatus=()=>({status,reason,signedIn:!!session});
const notice=()=>{window.dispatchEvent(new Event('salah:counter-status'));updateStatus();};
function lock(fn){return navigator.locks?.request?navigator.locks.request('salah:adhkar-progress-v2',fn):Promise.resolve(fn());}
function getEngine(){return engine||(engine=createCounterSync({storage:localStorage,uuid:()=>crypto.randomUUID(),withLock:lock,changed:kind=>{if(kind==='saved'||kind==='account')window.dispatchEvent(new Event('salah:counter-restored'));},request:async(uid,component)=>{
 const {data,error}=await accountAuthClient().auth.getSession();if(error||!data.session||data.session.user.id!==uid)throw Error('sign_in_required');
 const response=await fetch(OWNER_PROJECT_URL+'/functions/v1/adhkar-sync',{method:'POST',headers:{apikey:OWNER_PUBLIC_KEY,Authorization:'Bearer '+data.session.access_token,'Content-Type':'application/json'},body:JSON.stringify(component),cache:'no-store',credentials:'omit',referrerPolicy:'no-referrer',signal:AbortSignal.timeout(15000)});
 const result=await response.json();if(!response.ok)throw Error(result.error||'storage_unavailable');return result;
}}));}
export async function synchronizeCounters(){
 if(busy){schedule();return busy;}
 busy=(async()=>{try{const {data,error}=await accountAuthClient().auth.getSession();if(error)throw error;const next=data.session;const uid=next?.user?.id||null;session=next;await getEngine().activate(uid);if(!uid){status='local';reason='';notice();return{ok:false,reason:'signed_out'};}status='saving';notice();const result=await getEngine().sync();status=result.ok?'saved':'pending';reason=result.reason||'';notice();return result;}catch{status='pending';reason='storage_unavailable';notice();return{ok:false,reason};}})();try{return await busy;}finally{busy=null;}
}
function schedule(){clearTimeout(timer);timer=setTimeout(()=>synchronizeCounters(),700);}
export function initCounterAccounts(){
 accountAuthClient().auth.onAuthStateChange(()=>queueMicrotask(schedule));
 window.addEventListener('salah:counter-changed',schedule);
 window.addEventListener('storage',e=>{if(e.key==='salah:adhkar-progress-v2')schedule();});
 window.addEventListener('online',schedule);document.addEventListener('visibilitychange',()=>{if(!document.hidden)schedule();});setInterval(()=>{if(session&&!document.hidden)synchronizeCounters();},30000);schedule();
}
function statusText(){return status==='saved'?'Накопительный счёт сохранён в аккаунте.':status==='saving'?'Сохраняем счёт…':reason==='mfa_required'?'Подтвердите вход через Google Authenticator.':status==='pending'?'Счёт сохранён на устройстве. Синхронизация ожидает соединения.':'Счёт хранится на этом устройстве.';}
function updateStatus(){const el=document.getElementById('account-sync-status');if(el)el.textContent=statusText();const mfa=document.getElementById('account-mfa');if(mfa)mfa.hidden=reason!=='mfa_required';}
export async function showCounterAccount(container){
 host=container;container.innerHTML='<section class="panel section owner-login"><h1>Сохранение счёта</h1><p class="muted">Сохраняйте накопительный счёт азкаров в аккаунте и восстанавливайте его после переустановки или на другом телефоне.</p><p id="account-sync-status" class="muted" role="status">Проверяем вход…</p><div id="account-form-area"></div><a class="button" id="account-mfa" href="#admin" hidden>Подтвердить защищённый вход</a><details class="settings-extra"><summary>Какие данные сохраняются</summary><p class="muted">В аккаунте сохраняются ник, почта для входа и накопительные счётчики азкаров. История намазов, настройки и закладки остаются на устройстве.</p></details><a class="text-button" href="#more">Назад</a></section>';
 await synchronizeCounters();if(host!==container||!document.getElementById('account-form-area'))return;const area=container.querySelector('#account-form-area');
 if(session){area.innerHTML='<form id="counter-profile"><label for="counter-profile-nick">Ник</label><input id="counter-profile-nick" type="text" autocomplete="nickname" minlength="2" maxlength="40" required value="'+esc(session.user.user_metadata?.nickname||'')+'"><button class="text-button" type="submit">Сохранить ник</button></form><p>'+esc(session.user.email||'Ваш аккаунт')+'</p><button class="button" id="counter-sync-now">Сохранить счёт</button><button class="text-button" id="counter-account-out">Выйти</button>';area.querySelector('#counter-profile').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('button');button.disabled=true;const {error}=await accountAuthClient().auth.updateUser({data:{nickname:form.querySelector('input').value.trim()}});button.disabled=false;if(error)container.querySelector('#account-sync-status').textContent='Не удалось сохранить ник. Попробуйте позже.';else button.textContent='Ник сохранён';};area.querySelector('#counter-sync-now').onclick=()=>synchronizeCounters();area.querySelector('#counter-account-out').onclick=async()=>{const button=area.querySelector('#counter-account-out');button.disabled=true;await synchronizeCounters();const {error}=await accountAuthClient().auth.signOut({scope:'local'});if(error){button.disabled=false;container.querySelector('#account-sync-status').textContent='Не удалось выйти. Проверьте соединение.';return;}await synchronizeCounters();showCounterAccount(container);};}
 else{
  area.innerHTML='<form id="counter-account-email-form"><label for="counter-account-nickname">Ник</label><input id="counter-account-nickname" type="text" autocomplete="nickname" minlength="2" maxlength="40" required><label for="counter-account-email">Электронная почта</label><input id="counter-account-email" type="email" autocomplete="email" required><button class="button" type="submit">Получить код входа</button><p class="muted owner-note">При первом входе создаётся личный аккаунт. Счёт сохраняется только после подтверждения почты.</p></form><details class="settings-extra"><summary>Войти с паролем</summary><form id="counter-account-login"><label for="counter-password-email">Электронная почта</label><input id="counter-password-email" type="email" autocomplete="username" required><label for="counter-account-password">Пароль</label><input id="counter-account-password" type="password" autocomplete="current-password" required><button class="button" type="submit">Войти и сохранить счёт</button></form></details>';
  const mailForm=area.querySelector('#counter-account-email-form');mailForm.onsubmit=async e=>{e.preventDefault();const email=mailForm.querySelector('input[type=email]').value.trim(),nickname=mailForm.querySelector('#counter-account-nickname').value.trim(),button=mailForm.querySelector('button');button.disabled=true;if(nickname.length<2){button.disabled=false;container.querySelector('#account-sync-status').textContent='Укажите ник: от 2 до 40 символов.';return;}try{const {error}=await accountAuthClient().auth.signInWithOtp({email,options:{shouldCreateUser:true,data:{nickname}}});if(error)throw error;if(!mailForm.isConnected)return;mailForm.innerHTML='<p class="muted">Введите код из письма SALAH, отправленного на '+esc(email)+'. Можно проверить папку «Спам».</p><label for="counter-email-code">Код из письма</label><input id="counter-email-code" type="text" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6,8}" minlength="6" maxlength="8" required><button class="button" type="submit">Подтвердить и сохранить счёт</button><button class="text-button" type="button" id="counter-email-change">Изменить почту</button>';mailForm.querySelector('#counter-email-change').onclick=()=>showCounterAccount(container);mailForm.onsubmit=async event=>{event.preventDefault();const code=mailForm.querySelector('input'),submit=mailForm.querySelector('button');submit.disabled=true;try{const {error}=await accountAuthClient().auth.verifyOtp({email,token:code.value.trim(),type:'email'});code.value='';if(error)throw error;await accountAuthClient().auth.updateUser({data:{nickname}});await showCounterAccount(container);}catch{code.value='';submit.disabled=false;container.querySelector('#account-sync-status').textContent='Код неверен или истёк. Запросите новое письмо.';}};mailForm.querySelector('input').focus();container.querySelector('#account-sync-status').textContent='Письмо с кодом отправлено.';}catch{button.disabled=false;container.querySelector('#account-sync-status').textContent='Не удалось отправить письмо. Попробуйте через минуту.';}};
  area.querySelector('#counter-account-login').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('button');button.disabled=true;const password=form.querySelector('input[type=password]');try{const {error}=await accountAuthClient().auth.signInWithPassword({email:form.querySelector('input[type=email]').value.trim(),password:password.value});password.value='';if(error)throw error;await showCounterAccount(container);}catch{password.value='';button.disabled=false;container.querySelector('#account-sync-status').textContent='Не удалось войти. Проверьте почту и пароль.';}};
 }

 updateStatus();
}
